mapper.select:
SELECT  FROM beginner_project

    status = #{status}

        AND (full_name LIKE CONCAT('%', #{keyword}, '%') OR description_zh LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY update_time DESC, id DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM beginner_project

    status = #{status}

        AND (full_name LIKE CONCAT('%', #{keyword}, '%') OR description_zh LIKE CONCAT('%', #{keyword}, '%'))

SELECT  FROM beginner_project
WHERE last_verified_at IS NULL OR last_verified_at < #{before}
ORDER BY COALESCE(last_verified_at, '1970-01-01'), id LIMIT #{limit}

SELECT  FROM beginner_project
WHERE status = 'PUBLISHED'

    AND (
        topics_json LIKE CONCAT('%', #{topic}, '%') OR tech_stack LIKE CONCAT('%', #{topic}, '%')
    )


    AND primary_language IN
    #{language}

ORDER BY editorial_score DESC, beginner_score DESC, github_updated_at DESC, full_name ASC LIMIT #{limit}

SELECT selection_source FROM beginner_project_weekly_pick
WHERE week_start = #{weekStart}
ORDER BY rank_no LIMIT 1
